40 |     const separator = '─'.repeat(terminalWidth);
41 | 
42 |     // 显示初始菜单
43 |     console.log('');
44 |     console.log(separator);
45 | 
46 |     menuItems.forEach((item, index) => {
47 |         const isSelected = index === selectedIndex;
48 |         const prefix = isSelected ? '❯ ' : '  ';
49 | 
50 |         // 格式化：命令名（左对齐）+ 描述
51 |         const nameWidth = 25;
52 |         const paddedName = item.name.padEnd(nameWidth, ' ');
53 |         const line = `${prefix}${paddedName}${item.description}`;
54 | 
55 |         console.log(line);
56 |     });
57 | 
58 |     console.log(separator);
59 | 
60 |     const menuHeight = menuItems.length + 2; // 顶部线 + 选项 + 底部线
61 | 
62 |     return new Promise((resolve) => {
63 |         const stdin = process.stdin;
64 |         stdin.setRawMode(true);
65 |         stdin.resume();
66 |         stdin.setEncoding('utf-8');
67 | 
68 |         // 移动光标到第一个菜单项
69 |         readline.moveCursor(process.stdout, 0, -menuHeight);
70 | 
71 |         const redrawMenu = () => {
72 |             // 重新绘制整个菜单
73 |             readline.moveCursor(process.stdout, 0, -menuHeight);
74 | 
75 |             console.log(separator);
76 | 
77 |             menuItems.forEach((item, index) => {
78 |                 const isSelected = index === selectedIndex;
79 |                 const prefix = isSelected ? '❯ ' : '  ';
80 | 
