125 | /**
126 |  * 创建支持历史导航的 readline
127 |  */
128 | export function createReader(options: ReaderOptions): Promise<ReaderResult> {
129 |     return new Promise((resolve, reject) => {
130 |         const historyArray = [...options.history.getAll()].reverse();
131 | 
132 |         const rl = readline.createInterface({
133 |             input: process.stdin,
134 |             output: process.stdout,
135 |             prompt: options.prompt,
136 |             history: historyArray,
137 |             tabSize: 2,
138 |         });
139 | 
140 |         rl.prompt();
141 | 
142 |         rl.on('line', (line: string) => {
143 |             const trimmed = line.trim();
144 | 
145 |             // 输入 "/" 时显示可选择命令菜单
146 |             if (trimmed === '/') {
147 |                 rl.pause();
148 |                 showSelectableCommandMenu().then((selected) => {
149 |                     if (selected) {
150 |                         rl.close();
151 |                         resolve({
152 |                             value: selected,
153 |                             history: options.history,
154 |                         });
155 |                     } else {
156 |                         // 用户取消，继续等待输入
157 |                         rl.prompt();
158 |                     }
159 |                 });
160 |                 return;
161 |             }
162 | 
163 |             if (trimmed) {
164 |                 options.history.add(trimmed);
165 |             }
166 | 
167 |             rl.close();
168 |             resolve({
169 |                 value: trimmed,
170 |                 history: options.history,
171 |             });
172 |         });
173 | 
174 |         rl.on('SIGINT', () => {
175 |             rl.close();
176 |             process.exit(0);
177 |         });
178 | 
179 |         rl.on('error', (err) => {
180 |             reject(err);
181 |         });
182 |     });
183 | }
184 | 
185 | /**
186 |  * 读取用户输入（支持历史导航）
187 |  */
188 | export async function readWithHistory(
189 |     prompt: string,
190 |     history: InputHistory
191 | ): Promise<{ value: string; history: InputHistory }> {
192 |     return createReader({ prompt, history });
193 | }
194 | 
195 | /**
196 |  * 创建 readline 接口（供外部使用）
197 |  */
198 | export function createReadlineInterface(prompt: string): readline.ReadLine {
199 |     const rl = readline.createInterface({
200 |         input: process.stdin,
201 |         output: process.stdout,
202 |         prompt,
203 |     });
204 |     return rl;
205 | }
