193 |             const properties: Record<string, unknown> = {};
194 |             const required: string[] = [];
195 | 
196 |             for (const [key, value] of Object.entries(shape)) {
197 |                 const def = (value as any)._def;
198 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
199 | 
200 |                 // 检查是否是可选字段
201 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
202 |                                    (value as any).isOptional?.();
203 |                 if (!isOptional) {
204 |                     required.push(key);
205 |                 }
206 |             }
207 | 
208 |             return {
209 |                 type: 'object',
210 |                 properties,
211 |                 required: required.length > 0 ? required : undefined,
212 |                 additionalProperties: false,
213 |             };
214 |         }
215 | 
216 |         return { type: 'object', properties: {}, additionalProperties: false };
217 |     }
