219 |     /**
220 |      * 将 Zod 类型转换为 JSON Schema 类型
221 |      *
222 |      * @param def - Zod 类型定义
223 |      * @param key - 字段名（用于错误信息）
224 |      * @returns JSON Schema 类型定义
225 |      */
226 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
227 |         const typeName = def?.typeName;
228 | 
229 |         switch (typeName) {
230 |             case 'ZodString':
231 |                 return { type: 'string' };
232 | 
233 |             case 'ZodNumber':
234 |                 return { type: 'number' };
235 | 
236 |             case 'ZodBoolean':
237 |                 return { type: 'boolean' };
238 | 
239 |             case 'ZodNull':
240 |                 return { type: 'null' };
241 | 
242 |             case 'ZodArray':
243 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
244 |                 return {
245 |                     type: 'array',
246 |                     items: itemType,
247 |                 };
248 | 
249 |             case 'ZodObject':
250 |                 return this.zodToJsonSchema({ _def: def });
251 | 
252 |             case 'ZodOptional':
253 |             case 'ZodNullable':
254 |             case 'ZodDefault':
255 |                 // innerType 是 Zod 对象，需要获取其 _def
256 |                 return this.zodTypeToJsonSchema(def.innerType._def, key);
257 | 
258 |             case 'ZodEnum':
259 |                 return {
260 |                     type: 'string',
261 |                     enum: def.values,
262 |                 };
263 | 
264 |             case 'ZodLiteral':
265 |                 return {
266 |                     type: typeof def.value,
267 |                     const: def.value,
268 |                 };
269 | 
270 |             case 'ZodUnion':
271 |             case 'ZodDiscriminatedUnion':
272 |                 return {
273 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
274 |                 };
275 | 
276 |             case 'ZodEffects':
277 |                 // 处理带描述的字段
278 |                 const innerSchema = this.zodTypeToJsonSchema(def.innerType._def, key);
279 |                 if (def.description) {
280 |                     return { ...innerSchema, description: def.description };
281 |                 }
282 |                 return innerSchema;
283 | 
284 |             default:
285 |                 // 未知类型，使用 any
286 |                 if (typeName !== undefined) {
287 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
288 |                 } else {
289 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
290 |                 }
291 |                 return {};
292 |         }
293 |     }
294 | }
