87 | function fixTruncatedJson(json: string): string {
88 |   let result = json;
89 |   let inString = false;
90 |   let escapeNext = false;
91 |   let braceDepth = 0;
92 |   let bracketDepth = 0;
93 |   let lastUnquotedQuotePos = -1;
94 | 
95 |   for (let i = 0; i < result.length; i++) {
96 |     const char = result[i];
97 | 
98 |     if (escapeNext) {
99 |       escapeNext = false;
100 |       continue;
101 |     }
102 | 
103 |     if (char === '\\') {
104 |       escapeNext = true;
105 |       continue;
106 |     }
107 | 
108 |     if (char === '"') {
109 |       if (!inString) {
110 |         inString = true;
111 |         lastUnquotedQuotePos = i;
112 |       } else {
113 |         inString = false;
114 |         lastUnquotedQuotePos = -1;
115 |       }
116 |       continue;
117 |     }
118 | 
119 |     if (!inString) {
120 |       if (char === '{') braceDepth++;
121 |       if (char === '}') braceDepth--;
122 |       if (char === '[') bracketDepth++;
123 |       if (char === ']') bracketDepth--;
124 |     }
125 |   }
126 | 
127 |   // 如果字符串未闭合，尝试闭合它
128 |   if (inString && lastUnquotedQuotePos >= 0) {
129 |     // 检查是否在字符串值中（通常在 : 之后）
130 |     const beforeQuote = result.substring(0, lastUnquotedQuotePos);
131 |     const afterQuote = result.substring(lastUnquotedQuotePos + 1);
132 | 
133 |     // 简单策略：在末尾添加引号闭合字符串
134 |     result = result + '"';
135 |   }
136 | 
137 |   // 尝试闭合未完成的对象/数组
138 |   while (braceDepth > 0) {
139 |     result = result + '}';
140 |     braceDepth--;
141 |   }
142 |   while (bracketDepth > 0) {
143 |     result = result + ']';
144 |     bracketDepth--;
145 |   }
146 | 
147 |   return result;
148 | }
