328 | /**
329 |  * OpenAI API provider
330 |  *
331 |  * Uses the OpenAI Chat Completions API.
332 |  */
333 | export class OpenAIProvider extends LLMProvider {
334 |   baseURL: string
335 |   model: string
336 |   maxTokens: number;
337 |   maxOutputTokens: number;
338 | 
339 |   constructor(config: OpenAIConfig) {
340 |     super(config)
341 |     this.baseURL = config.baseURL || 'https://api.openai.com/v1'
342 |     this.model = config.model || 'gpt-4o-mini'
343 |     this.maxTokens = config.maxTokens || 128 * 1024;
344 |     this.maxOutputTokens = config.maxOutputTokens || 8000;
345 |   }
346 | 
347 |   async generate(messages: Message[], options?: LLMOptions): Promise<LLMResponse | null> {
348 |     const { model, max_tokens, temperature, tools } = options || {}
349 |     const MAX_CONTINUE_ROUNDS = 2; // 最多续写 2 次
350 | 
351 |     let accumulatedContent = '';
352 |     let accumulatedToolCalls: Array<{
353 |       id: string;
354 |       type: 'function';
355 |       function: { name: string; arguments: string };
356 |     }> = [];
357 |     let totalUsage = {
358 |       prompt_tokens: 0,
359 |       completion_tokens: 0,
360 |       total_tokens: 0,
361 |     };
362 | 
363 |     let currentMessages = [...messages];
364 |     let continueRound = 0;
365 | 
366 |     while (continueRound <= MAX_CONTINUE_ROUNDS) {
367 |       try {
368 |         const requestBody: Record<string, unknown> = {
369 |           model: model || this.model,
370 |           messages: currentMessages,
371 |           max_tokens: max_tokens || this.maxOutputTokens,
372 |           temperature: temperature || 0.1,
373 |         };
374 | 
375 |         // 添加 tools 参数（如果提供）
376 |         if (tools && tools.length > 0) {
377 |           requestBody.tools = tools;
378 |         }
379 | 
380 |         const response = await fetch(`${this.baseURL}/chat/completions`, {
381 |           method: 'POST',
382 |           headers: {
383 |             'Content-Type': 'application/json',
384 |             'Authorization': `Bearer ${this.config.apiKey}`,
385 |           },
386 |           body: JSON.stringify(requestBody),
387 |         });
388 | 
389 |         if (!response.ok) {
390 |           const errorBody = await response.text();
391 |           console.error('API Error Response:', errorBody);
392 |           throw new Error(`API request failed: ${response.status} ${response.statusText}\n${errorBody}`);
393 |         }
394 | 
395 |         const data = await response.json() as ChatCompletionResponse;
396 |         const finishReason = data.choices[0]?.finish_reason;
397 | 
398 |         // 累加使用量
399 |         if (data.usage) {
400 |           totalUsage.prompt_tokens += data.usage.prompt_tokens;
401 |           totalUsage.completion_tokens += data.usage.completion_tokens;
402 |           totalUsage.total_tokens += data.usage.total_tokens;
403 |         }
404 | 
405 |         const messageContent = data.choices[0]?.message?.content || '';
406 |         const messageToolCalls = data.choices[0]?.message?.tool_calls || [];
407 | 
408 |         // 尝试修复 tool_calls 中可能格式错误的 arguments
409 |         const fixedToolCalls = messageToolCalls.map(tc => ({
410 |           ...tc,
411 |           function: {
412 |             ...tc.function,
413 |             arguments: fixMalformedJson(tc.function.arguments),
414 |           },
415 |         }));
416 | 
417 |         // 累加内容
418 |         if (continueRound === 0) {
419 |           accumulatedContent = messageContent;
420 |           accumulatedToolCalls = fixedToolCalls;
421 |         } else {
422 |           // 续写时追加内容
423 |           accumulatedContent += messageContent;
424 |           // 续写时可能需要合并 tool_calls
425 |           if (fixedToolCalls.length > 0) {
426 |             accumulatedToolCalls = fixedToolCalls;
427 |           }
428 |         }
429 | 
430 |         // 检查是否需要续写
431 |         if (finishReason === 'length' && continueRound < MAX_CONTINUE_ROUNDS) {
432 |           // 需要续写
433 |           continueRound++;
434 | 
435 |           // 构建续写消息：将当前部分响应作为 assistant 消息添加
436 |           currentMessages = [
437 |             ...currentMessages,
438 |             {
439 |               role: 'assistant' as const,
440 |               content: accumulatedContent,
441 |               tool_calls: messageToolCalls, // 使用原始的 tool_calls 用于续写
442 |             },
443 |           ];
444 | 
445 |           console.log(`[OpenAIProvider] Response truncated, continuing... (round ${continueRound}/${MAX_CONTINUE_ROUNDS})`);
446 |           continue;
447 |         }
448 | 
449 |         // 正常返回
450 |         return {
451 |           content: accumulatedContent,
452 |           role: 'assistant',
453 |           type: data.choices[0]?.message?.type || 'text',
454 |           tool_calls: accumulatedToolCalls,
455 |           usage: totalUsage,
456 |         };
457 | 
458 |       } catch (error) {
459 |         // 如果在续写过程中出错，返回已累积的内容
460 |         if (continueRound > 0) {
461 |           console.warn('[OpenAIProvider] Error during continuation, returning partial result:', error);
462 |           return {
463 |             content: accumulatedContent || 'LLM API error: ' + (error instanceof Error ? error.message : 'Unknown error'),
464 |             role: 'assistant',
465 |             type: 'text',
466 |             tool_calls: accumulatedToolCalls,
467 |             usage: totalUsage,
468 |           };
469 |         }
470 | 
471 |         console.error('OpenAI API error:', error);
472 |         const errorMsg = error instanceof Error ? error.message : 'Unknown error';
473 |         return {
474 |           content: 'LLM API error: ' + errorMsg,
475 |           role: 'assistant',
476 |           type: 'text',
477 |           tool_calls: [],
478 |           usage: {
479 |             prompt_tokens: 0,
480 |             completion_tokens: 0,
481 |             total_tokens: 0,
482 |           },
483 |         };
484 |       }
485 |     }
486 | 
487 |     // 不应该到这里，但作为保险
488 |     return {
489 |       content: accumulatedContent,
490 |       role: 'assistant',
491 |       type: 'text',
492 |       tool_calls: accumulatedToolCalls,
493 |       usage: totalUsage,
494 |     };
495 |   }
496 | 
497 | }
