35 |   /** 服务器配置 */
36 |   private config: McpServerConfig;
37 | 
38 |   /** 子进程 */
39 |   private process: ChildProcess | null = null;
40 | 
41 |   /** 连接状态 */
42 |   private _state: ConnectionState = ConnectionState.Disconnected;
43 | 
44 |   /** 请求ID计数器 */
45 |   private requestId = 0;
46 | 
47 |   /** 待处理的请求 */
48 |   private pendingRequests = new Map<number | string, {
49 |     resolve: (value: JsonRpcResponse) => void;
50 |     reject: (error: Error) => void;
51 |     timeout: NodeJS.Timeout;
52 |   }>();
53 | 
54 |   /** 请求超时时间（毫秒） */
55 |   private readonly REQUEST_TIMEOUT = 120000;
