148 |   // -------------------------------------------------------------------------
149 |   // Protocol Methods
150 |   // -------------------------------------------------------------------------
151 | 
152 |   /**
153 |    * 初始化连接
154 |    */
155 |   private async initialize(): Promise<InitializeResult> {
156 |     const initParams: InitializeParams = {
157 |       protocolVersion: '2025-11-25',
158 |       capabilities: {
159 |         roots: {},
160 |       },
161 |       clientInfo: {
162 |         name: 'ai-agent-v2',
163 |         version: '1.0.0',
164 |       },
165 |     };
166 | 
167 |     const response = await this.sendRequest('initialize', initParams as any);
168 |     this.initializeResult = response.result as unknown as InitializeResult;
169 |     return this.initializeResult!;
170 |   }
