222 |      */
223 |     private async cleanOldBackups(filePath: string): Promise<void> {
224 |         const backups = this.backupIndex.get(filePath);
225 |         if (!backups || backups.length <= this.maxBackups) {
226 |             return;
227 |         }
228 | 
229 |         // 按创建时间排序，删除最旧的
230 |         const sortedBackups = [...backups].sort((a, b) => a.createdAt - b.createdAt);
231 |         const toDelete = sortedBackups.slice(0, sortedBackups.length - this.maxBackups);
232 | 
233 |         for (const backup of toDelete) {
