117 |  * 构建跨平台的文件列表命令
118 |  *
119 |  * @param directory - 目录
120 |  * @returns 跨平台命令字符串
121 |  */
122 | export function buildListCommand(directory: string = '.'): string {
123 |     const platform = getPlatform();
124 | 
125 |     switch (platform) {
126 |         case 'windows': {
127 |             const normDir = directory.replace(/\//g, '\\');
128 |             return `dir /a "${normDir}"`;
129 |         }
130 | 
131 |         case 'mac':
132 |         case 'linux':
133 |             return `ls -la "${directory}"`;
134 | 
135 |         default:
136 |             throw new Error(`Unsupported platform: ${platform}`);
137 |     }
138 | }
