184 | /**
185 |  * 执行跨平台命令（同步）
186 |  */
187 | export function execCommand(command: string): { stdout: string; stderr: string; exitCode: number } {
188 |     const platform = getPlatform();
189 |     try {
190 |         const result = execaCommandSync(command, {
191 |             shell: true,
192 |             encoding: 'buffer' as any
193 |         });
194 |         return {
195 |             stdout: decodeCommandOutput(result.stdout, platform),
196 |             stderr: decodeCommandOutput(result.stderr, platform),
197 |             exitCode: result.exitCode ?? 0
198 |         };
199 |     } catch (error: any) {
200 |         return {
201 |             stdout: decodeCommandOutput(error.stdout, platform),
202 |             stderr: decodeCommandOutput(error.stderr || error.message, platform),
203 |             exitCode: error.exitCode || 1
204 |         };
205 |     }
206 | }
