213 |  * @param options.timeout - 超时时间（毫秒）
214 |  * @param options.cwd - 工作目录
215 |  * @returns 执行结果
216 |  */
217 | export async function execCommandAsync(
218 |     command: string,
219 |     options?: { timeout?: number; cwd?: string }
220 | ): Promise<{
221 |     stdout: string;
222 |     stderr: string;
223 |     exitCode: number;
224 | }> {
225 |     const platform = getPlatform();
226 |     try {
