231 |             cwd: options?.cwd,
232 |         });
233 |         return {
234 |             stdout: decodeCommandOutput(result.stdout, platform),
235 |             stderr: decodeCommandOutput(result.stderr, platform),
236 |             exitCode: result.exitCode ?? 0
237 |         };
238 |     } catch (error: any) {
239 |         return {
240 |             stdout: decodeCommandOutput(error.stdout, platform),
241 |             stderr: decodeCommandOutput(error.stderr || error.message, platform),
242 |             exitCode: error.exitCode || 1
243 |         };
244 |     }
245 | }
